func TestTmpLateRoute(t *testing.T) {
	router := New()
	w := httptest.NewRecorder()
	req, _ := http.NewRequest("GET", "/test/john/smith/is/super/great", nil)
	router.ServeHTTP(w, req)
	if w.Code != 404 {
		t.Fatal("first", w.Code)
	}
	router.GET("/test/:name/:last_name/*wild", func(c *Context) {
		c.String(200, "%s %s %s", c.Param("name"), c.Params.ByName("last_name"), c.Param("wild"))
