	w2 := httptest.NewRecorder()
	req2, _ := http.NewRequest("GET", "/test/john/smith/is/super/great", nil)
	router.ServeHTTP(w2, req2)
	t.Log("second:", w2.Code, w2.Body.String())
	if w2.Body.String() != "john smith /is/super/great" {
		t.Fatal("params wrong:", w2.Body.String())
	}
}

func TestTmpFixedPath(t *testing.T) {
	r := New()
	r.RedirectFixedPath = true
	h := func(c *Context) { c.String(200, "ok") }
	r.GET("/prefix/:id", h)
	r.GET("/prefix/xxx", h)
	w := httptest.NewRecorder()
	req, _ := http.NewRequest("GET", "/PREFIX/XXX", nil)
	r.ServeHTTP(w, req)
	t.Log("PREFIX/XXX ->", w.Code, w.Header().Get("Location"))
	if w.Code != 301 || w.Header().Get("Location") != "/prefix/xxx" {
		t.Fatal("expected redirect to /prefix/xxx, got", w.Code, w.Header().Get("Location"))
	}
